begin;
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade, trader_name text not null, preferred_language text not null default 'en' check(preferred_language in ('en','yo','ha','ig')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.businesses(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users, name text not null, category text not null, location text, allow_negative_stock boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.business_memberships(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, user_id uuid not null references auth.users, role text not null default 'owner' check(role in ('owner','staff')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,user_id));
create function public.can_access(b uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from businesses where id=b and owner_id=auth.uid()) or exists(select 1 from business_memberships where business_id=b and user_id=auth.uid()); $$;
create table public.products(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, name text not null, category text not null default 'General', selling_price numeric(14,2) not null check(selling_price>=0), cost_price numeric(14,2) check(cost_price>=0), stock_quantity integer not null default 0, low_stock_threshold integer not null default 5 check(low_stock_threshold>=0), archived boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id));
create table public.customers(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, name text not null, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id));
create table public.voice_interactions(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, created_by uuid not null references auth.users, transcript text not null, language text not null, model text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id));
create table public.sales(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, customer_id uuid, total numeric(14,2) not null default 0 check(total>=0), paid_amount numeric(14,2) not null default 0 check(paid_amount>=0 and paid_amount<=total), payment_status text not null check(payment_status in ('paid','unpaid','partial','unknown')), source text not null check(source in ('voice','manual')), voice_interaction_id uuid, idempotency_key uuid not null, reversed_at timestamptz, reversal_reason text, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,idempotency_key), unique(business_id,id), foreign key(business_id,customer_id) references public.customers(business_id,id), foreign key(business_id,voice_interaction_id) references public.voice_interactions(business_id,id), check(source<>'voice' or voice_interaction_id is not null));
create table public.sale_items(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, sale_id uuid not null, product_id uuid not null, product_name text not null, quantity integer not null check(quantity>0), unit_price numeric(14,2) not null check(unit_price>=0), cost_price numeric(14,2), line_total numeric(14,2) generated always as (quantity*unit_price) stored, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(business_id,sale_id) references public.sales(business_id,id), foreign key(business_id,product_id) references public.products(business_id,id));
create table public.stock_movements(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, product_id uuid not null, sale_id uuid, quantity integer not null check(quantity<>0), reason text not null, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(business_id,product_id) references public.products(business_id,id), foreign key(business_id,sale_id) references public.sales(business_id,id));
create table public.expenses(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, amount numeric(14,2) not null check(amount>0), category text not null, description text not null, occurred_on date not null default current_date, idempotency_key uuid not null, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,idempotency_key));
alter table public.stock_movements add column idempotency_key uuid, add unique(business_id,idempotency_key);
create table public.debts(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, customer_id uuid not null, sale_id uuid, amount numeric(14,2) not null check(amount>0), description text not null, idempotency_key uuid not null, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id), unique(business_id,idempotency_key), foreign key(business_id,customer_id) references public.customers(business_id,id), foreign key(business_id,sale_id) references public.sales(business_id,id));
create table public.debt_repayments(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, debt_id uuid not null, amount numeric(14,2) not null check(amount>0), idempotency_key uuid not null, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,idempotency_key), foreign key(business_id,debt_id) references public.debts(business_id,id));
create table public.ajo_groups(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, name text not null, contribution_amount numeric(14,2) not null check(contribution_amount>0), frequency text not null default 'weekly' check(frequency in ('daily','weekly','monthly')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id));
create table public.ajo_memberships(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, group_id uuid not null, name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,id), unique(business_id,group_id,id), foreign key(business_id,group_id) references public.ajo_groups(business_id,id));
create table public.ajo_contributions(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, group_id uuid not null, member_id uuid not null, amount numeric(14,2) not null check(amount>0), occurred_on date not null default current_date, idempotency_key uuid not null, created_by uuid not null references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(business_id,idempotency_key), foreign key(business_id,group_id,member_id) references public.ajo_memberships(business_id,group_id,id));
create table public.ajo_payouts(like public.ajo_contributions including defaults including constraints including generated);
alter table public.ajo_payouts add primary key(id), add unique(business_id,idempotency_key), add foreign key(business_id) references public.businesses, add foreign key(created_by) references auth.users, add foreign key(business_id,group_id,member_id) references public.ajo_memberships(business_id,group_id,id);
create table public.transaction_suggestions(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, voice_interaction_id uuid not null, intent jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(business_id,voice_interaction_id) references public.voice_interactions(business_id,id));
create table public.activity_events(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses, created_by uuid not null references auth.users, action text not null, entity_id uuid, details jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create function public.touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
alter table public.profiles enable row level security;
create policy own_profile on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.businesses enable row level security;
create policy read_business on public.businesses for select to authenticated using(owner_id=auth.uid() or public.can_access(id));
create policy create_business on public.businesses for insert to authenticated with check(owner_id=auth.uid());
create policy update_business on public.businesses for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
alter table public.business_memberships enable row level security;
create policy read_members on public.business_memberships for select to authenticated using(public.can_access(business_id));
create policy owner_members on public.business_memberships for insert to authenticated with check(exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=auth.uid()));
do $$ declare t text; begin
 foreach t in array array['products','customers','voice_interactions','sales','sale_items','stock_movements','expenses','debts','debt_repayments','ajo_groups','ajo_memberships','ajo_contributions','ajo_payouts','transaction_suggestions','activity_events'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy tenant_read on public.%I for select to authenticated using(public.can_access(business_id))',t);
 execute format('create index on public.%I (business_id, created_at desc)',t);
 end loop;
 foreach t in array array['profiles','businesses','business_memberships','products','customers','voice_interactions','sales','sale_items','stock_movements','expenses','debts','debt_repayments','ajo_groups','ajo_memberships','ajo_contributions','ajo_payouts','transaction_suggestions','activity_events'] loop
 execute format('create trigger touch_updated before update on public.%I for each row execute function public.touch_updated()',t);
 end loop;
end $$;
-- Browsers have read access only to financial records. All writes use the authenticated Express transaction boundary.
do $$ begin if not exists(select 1 from pg_roles where rolname='beta_api') then create role beta_api nologin; end if; end $$;
grant beta_api to postgres;
grant usage on schema public,auth to beta_api;
grant execute on function auth.uid(), public.can_access(uuid) to beta_api;
grant select,insert,update on all tables in schema public to beta_api;
grant select on all tables in schema public to authenticated;
grant insert,update on public.profiles,public.businesses to authenticated;
do $$ declare t text; begin
 foreach t in array array['profiles','businesses','business_memberships','products','customers','voice_interactions','sales','sale_items','stock_movements','expenses','debts','debt_repayments','ajo_groups','ajo_memberships','ajo_contributions','ajo_payouts','transaction_suggestions','activity_events'] loop
 if t='profiles' then execute 'create policy api_access on profiles for all to beta_api using(id=auth.uid()) with check(id=auth.uid())';
 elsif t='businesses' then execute 'create policy api_access on businesses for all to beta_api using(owner_id=auth.uid() or public.can_access(id)) with check(owner_id=auth.uid())';
 else execute format('create policy api_access on public.%I for all to beta_api using(public.can_access(business_id)) with check(public.can_access(business_id))',t); end if;
 end loop;
end $$;
revoke all on function public.can_access(uuid) from public;
grant execute on function public.can_access(uuid) to authenticated,beta_api;
commit;
